@leadingCoeff_prod : ∀ {R : Type u_1} {ι : Type u_2} (s : Finset ι) [inst : CommSemiring R] [NoZeroDivisors R]
  (f : ι → R[X]), (∏ i ∈ s, f i).leadingCoeff = ∏ i ∈ s, (f i).leadingCoeff
@natDegree_prod : ∀ {R : Type u_1} {ι : Type u_2} (s : Finset ι) [inst : CommSemiring R] [NoZeroDivisors R]
  (f : ι → R[X]), (∀ i ∈ s, f i ≠ 0) → (∏ i ∈ s, f i).natDegree = ∑ i ∈ s, (f i).natDegree
@Polynomial.map_prod : ∀ {R : Type u_1} {S : Type u_2} [inst : CommSemiring R] [inst_1 : CommSemiring S] (f : R →+* S)
  {ι : Type u_3} (g : ι → R[X]) (s : Finset ι), map f (∏ i ∈ s, g i) = ∏ i ∈ s, map f (g i)
@eval_eq_sum_range' : ∀ {R : Type u_1} [inst : Semiring R] {p : R[X]} {n : ℕ},
  p.natDegree < n → ∀ (x : R), eval x p = ∑ i ∈ Finset.range n, p.coeff i * x ^ i
@Finset.sum_coe_sort : ∀ {ι : Type u_1} {M : Type u_2} (s : Finset ι) [inst : AddCommMonoid M] (f : ι → M),
  ∑ i, f ↑i = ∑ i ∈ s, f i
@leadingCoeff_X_add_C : ∀ {S : Type u_1} [inst : Semiring S] (r : S), (X + C r).leadingCoeff = 1
@coeff_map : ∀ {R : Type u_1} {S : Type u_2} [inst : Semiring R] {p : R[X]} [inst_1 : Semiring S] (f : R →+* S) (n : ℕ),
  (map f p).coeff n = f (p.coeff n)
